import { useRef, useMemo, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Line } from '@react-three/drei';
import * as THREE from 'three';
import { Scenario } from '../types';
import { useStore } from '../store';
import { predictTrajectory } from '../algorithms/kalmanFilter';

interface Props {
  scenario: Scenario;
}

function PointCloud({ scenario }: Props) {
  const { playback } = useStore();
  const pointsRef = useRef<THREE.Points>(null);
  const boxesRef = useRef<THREE.Group>(null);

  // Get current frame based on playback time
  const currentFrameIndex = useMemo(() => {
    const fps = 10; // 0.1s per frame
    const index = Math.floor(playback.currentTime * fps);
    return Math.min(index, scenario.lidarFrames.length - 1);
  }, [playback.currentTime, scenario.lidarFrames.length]);

  const currentFrame = scenario.lidarFrames[currentFrameIndex];

  // Create point cloud geometry
  const pointsGeometry = useMemo(() => {
    const geometry = new THREE.BufferGeometry();
    const points = currentFrame.points;

    // Extract positions
    const positions = new Float32Array(points.length / 7 * 3);
    const colors = new Float32Array(points.length / 7 * 3);

    for (let i = 0; i < points.length / 7; i++) {
      const idx = i * 7;
      positions[i * 3] = points[idx];
      positions[i * 3 + 1] = points[idx + 1];
      positions[i * 3 + 2] = points[idx + 2];
      colors[i * 3] = points[idx + 3];
      colors[i * 3 + 1] = points[idx + 4];
      colors[i * 3 + 2] = points[idx + 5];
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    return geometry;
  }, [currentFrame]);

  // Animate point fade-in
  useFrame(() => {
    if (pointsRef.current) {
      const material = pointsRef.current.material as THREE.PointsMaterial;
      material.opacity = THREE.MathUtils.lerp(material.opacity, 1, 0.1);
    }
  });

  useEffect(() => {
    if (pointsRef.current) {
      const material = pointsRef.current.material as THREE.PointsMaterial;
      material.opacity = 0.3;
    }
  }, [currentFrameIndex]);

  return (
    <>
      {/* Point Cloud */}
      <points ref={pointsRef} geometry={pointsGeometry}>
        <pointsMaterial
          size={0.08}
          vertexColors
          transparent
          opacity={1}
          sizeAttenuation
        />
      </points>

      {/* Bounding Boxes */}
      <group ref={boxesRef}>
        {currentFrame.trackedObjects.map((obj) => (
          <BoundingBox key={obj.id} object={obj} />
        ))}
      </group>
    </>
  );
}

function BoundingBox({ object }: { object: any }) {
  const meshRef = useRef<THREE.Mesh>(null);

  // Predict future trajectory using Kalman filter
  const trajectory = useMemo(() => {
    return predictTrajectory(object, 20, 0.1);
  }, [object]);

  const color = useMemo(() => {
    switch (object.type) {
      case 'pedestrian':
        return '#ef4444';
      case 'vehicle':
        return '#3b82f6';
      case 'cyclist':
        return '#f59e0b';
      case 'animal':
        return '#8b5cf6';
      default:
        return '#6b7280';
    }
  }, [object.type]);

  useFrame(() => {
    if (meshRef.current) {
      meshRef.current.rotation.y += 0.005;
    }
  });

  return (
    <group>
      {/* Bounding Box */}
      <mesh
        ref={meshRef}
        position={[
          object.boundingBox.center.x,
          object.boundingBox.center.y,
          object.boundingBox.center.z,
        ]}
      >
        <boxGeometry
          args={[
            object.boundingBox.dimensions.x,
            object.boundingBox.dimensions.y,
            object.boundingBox.dimensions.z,
          ]}
        />
        <meshBasicMaterial color={color} wireframe transparent opacity={0.6} />
      </mesh>

      {/* Label */}
      <mesh
        position={[
          object.boundingBox.center.x,
          object.boundingBox.center.y + object.boundingBox.dimensions.y / 2 + 0.5,
          object.boundingBox.center.z,
        ]}
      >
        <boxGeometry args={[1, 0.3, 0.1]} />
        <meshBasicMaterial color="#000" opacity={0.7} transparent />
      </mesh>

      {/* Predicted Trajectory */}
      {trajectory.length > 0 && (
        <TrajectoryLine points={trajectory} color={color} />
      )}
    </group>
  );
}

function TrajectoryLine({ points, color }: { points: any[]; color: string }) {
  const linePoints = useMemo(() => {
    return points.map((p) => [p.x, p.y, p.z] as [number, number, number]);
  }, [points]);

  return (
    <Line
      points={linePoints}
      color={color}
      lineWidth={2}
      transparent
      opacity={0.4}
    />
  );
}

function Scene({ scenario }: Props) {
  return (
    <>
      <ambientLight intensity={0.5} />
      <pointLight position={[10, 10, 10]} intensity={0.8} />
      <pointLight position={[-10, -10, -10]} intensity={0.3} />

      <PointCloud scenario={scenario} />

      <Grid
        args={[100, 100]}
        position={[0, 0, 0]}
        cellSize={5}
        cellThickness={0.5}
        cellColor="#333"
        sectionSize={20}
        sectionThickness={1}
        sectionColor="#444"
        fadeDistance={100}
        fadeStrength={1}
      />

      <OrbitControls
        enablePan={true}
        enableZoom={true}
        enableRotate={true}
        minDistance={5}
        maxDistance={100}
        target={[0, 2, 0]}
      />
    </>
  );
}

export default function LiDARViewer({ scenario }: Props) {
  return (
    <Canvas
      camera={{ position: [30, 15, 30], fov: 60 }}
      style={{ background: '#0a0a0a' }}
    >
      <Scene scenario={scenario} />
    </Canvas>
  );
}
