import { Scenario, Vector3 } from '../types';
import { generatePointCloud } from '../algorithms/pointCloud';

/**
 * Generate mock scenario data for 10 diverse edge cases
 * Each scenario includes realistic multi-sensor data
 */

function generateTrackHistory(center: Vector3, steps: number): Vector3[] {
  const history: Vector3[] = [];
  let current = { ...center };

  for (let i = 0; i < steps; i++) {
    history.push({ ...current });
    // Add some random motion
    current.x += (Math.random() - 0.5) * 0.5;
    current.y += (Math.random() - 0.5) * 0.1;
    current.z += (Math.random() - 0.5) * 0.5;
  }

  return history;
}

