import { create } from 'zustand';
import { Scenario, SearchFilters, PlaybackState } from './types';

interface AppState {
  // Search state
  searchQuery: string;
  searchResults: Scenario[];
  filters: SearchFilters;
  isSearching: boolean;

  // Selected scenario
  selectedScenario: Scenario | null;

  // Playback state
  playback: PlaybackState;

  // UI state
  view: 'search' | 'viewer';
  sidebarOpen: boolean;

  // Actions
  setSearchQuery: (query: string) => void;
  setSearchResults: (results: Scenario[]) => void;
  setFilters: (filters: SearchFilters) => void;
  setIsSearching: (isSearching: boolean) => void;
  selectScenario: (scenario: Scenario | null) => void;
  setPlayback: (playback: Partial<PlaybackState>) => void;
  setView: (view: 'search' | 'viewer') => void;
  toggleSidebar: () => void;
  resetPlayback: () => void;
}

export const useStore = create<AppState>((set) => ({
  searchQuery: '',
  searchResults: [],
  filters: {
    timeOfDay: [],
    weather: [],
    objectTypes: [],
    complexity: [],
  },
  isSearching: false,

  selectedScenario: null,

  playback: {
    isPlaying: false,
    currentTime: 0,
    duration: 0,
    playbackSpeed: 1.0,
  },

  view: 'search',
  sidebarOpen: true,

  setSearchQuery: (query) => set({ searchQuery: query }),
  setSearchResults: (results) => set({ searchResults: results }),
  setFilters: (filters) => set({ filters }),
  setIsSearching: (isSearching) => set({ isSearching }),
  selectScenario: (scenario) => set({
    selectedScenario: scenario,
    view: scenario ? 'viewer' : 'search',
    playback: {
      isPlaying: false,
      currentTime: 0,
      duration: scenario?.duration || 0,
      playbackSpeed: 1.0,
    }
  }),
  setPlayback: (playback) => set((state) => ({
    playback: { ...state.playback, ...playback }
  })),
  setView: (view) => set({ view }),
  toggleSidebar: () => set((state) => ({ sidebarOpen: !state.sidebarOpen })),
  resetPlayback: () => set({
    playback: {
      isPlaying: false,
      currentTime: 0,
      duration: 0,
      playbackSpeed: 1.0,
    }
  }),
}));
