import { AlertTriangle, Info, AlertCircle } from 'lucide-react';
import { Scenario } from '../types';
import { useStore } from '../store';

interface Props {
  scenario: Scenario;
}

export default function TimelineEvents({ scenario }: Props) {
  const { playback, setPlayback } = useStore();

  const handleEventClick = (time: number) => {
    setPlayback({ currentTime: time, isPlaying: false });
  };

  const getEventIcon = (severity: string) => {
    switch (severity) {
      case 'critical':
        return <AlertTriangle size={16} />;
      case 'warning':
        return <AlertCircle size={16} />;
      default:
        return <Info size={16} />;
    }
  };

  const getEventColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return '#ef4444';
      case 'warning':
        return '#f59e0b';
      default:
        return '#3b82f6';
    }
  };

  return (
    <div className="timeline-events">
      <h3 className="timeline-title">Critical Events</h3>
      <div className="events-list">
        {scenario.eventTimestamps.map((event, i) => {
          const isActive =
            Math.abs(playback.currentTime - event.time) < 0.5;
          const position = (event.time / scenario.duration) * 100;

          return (
            <div
              key={i}
              className={`event-item ${event.severity} ${isActive ? 'active' : ''}`}
              onClick={() => handleEventClick(event.time)}
            >
              <div className="event-marker">
                <div
                  className="event-indicator"
                  style={{
                    left: `${position}%`,
                    background: getEventColor(event.severity),
                  }}
                />
              </div>
              <div className="event-content">
                <div className="event-header">
                  {getEventIcon(event.severity)}
                  <span className="event-time">
                    {event.time.toFixed(1)}s
                  </span>
                </div>
                <p className="event-description">{event.description}</p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
