import { useMemo } from 'react';
import { Activity, MapPin, Thermometer, Wind, Eye } from 'lucide-react';
import { Scenario } from '../types';
import { useStore } from '../store';
import { calculateDensity } from '../algorithms/pointCloud';

interface Props {
  scenario: Scenario;
}

export default function MetadataOverlay({ scenario }: Props) {
  const { playback } = useStore();

  // Get current frame
  const currentFrameIndex = useMemo(() => {
    const fps = 10;
    const index = Math.floor(playback.currentTime * fps);
    return Math.min(index, scenario.lidarFrames.length - 1);
  }, [playback.currentTime, scenario.lidarFrames.length]);

  const currentFrame = scenario.lidarFrames[currentFrameIndex];

  // Calculate metrics
  const pointDensity = useMemo(() => {
    return calculateDensity(currentFrame.points);
  }, [currentFrame]);

  const avgConfidence = useMemo(() => {
    if (currentFrame.trackedObjects.length === 0) return 0;
    const sum = currentFrame.trackedObjects.reduce(
      (acc, obj) => acc + obj.confidence,
      0
    );
    return sum / currentFrame.trackedObjects.length;
  }, [currentFrame]);

  const formatWeather = (weather: string) => {
    return weather.replace(/_/g, ' ');
  };

  return (
    <div className="metadata-overlay">
      <div className="metadata-section">
        <h3 className="metadata-title">
          <Activity size={16} />
          Sensor Data
        </h3>
        <div className="metadata-grid">
          <div className="metadata-item">
            <span className="label">Frame</span>
            <span className="value">
              {currentFrameIndex + 1} / {scenario.lidarFrames.length}
            </span>
          </div>
          <div className="metadata-item">
            <span className="label">Point Density</span>
            <span className="value">{pointDensity.toFixed(1)} pts/m³</span>
          </div>
          <div className="metadata-item">
            <span className="label">Points</span>
            <span className="value">
              {(currentFrame.points.length / 7).toFixed(0)}
            </span>
          </div>
        </div>
      </div>

      <div className="metadata-section">
        <h3 className="metadata-title">
          <MapPin size={16} />
          Environment
        </h3>
        <div className="metadata-grid">
          <div className="metadata-item">
            <span className="label">
              <Thermometer size={12} />
              Temperature
            </span>
            <span className="value">{scenario.weather.temperature}°C</span>
          </div>
          <div className="metadata-item">
            <span className="label">
              <Wind size={12} />
              Wind
            </span>
            <span className="value">{scenario.weather.windSpeed} m/s</span>
          </div>
          <div className="metadata-item">
            <span className="label">
              <Eye size={12} />
              Visibility
            </span>
            <span className="value">{scenario.weather.visibility}m</span>
          </div>
          <div className="metadata-item">
            <span className="label">Weather</span>
            <span className="value">
              {formatWeather(scenario.weather.precipitation)}
            </span>
          </div>
        </div>
      </div>

      <div className="metadata-section">
        <h3 className="metadata-title">Tracked Objects</h3>
        <div className="tracked-objects">
          {currentFrame.trackedObjects.length === 0 ? (
            <p className="no-objects">No objects detected</p>
          ) : (
            currentFrame.trackedObjects.map((obj) => (
              <div key={obj.id} className="tracked-object">
                <div className="object-header">
                  <span className={`object-type ${obj.type}`}>{obj.type}</span>
                  <span className="object-id">{obj.id}</span>
                </div>
                <div className="object-stats">
                  <div className="confidence-bar">
                    <div
                      className="confidence-fill"
                      style={{
                        width: `${obj.confidence * 100}%`,
                        background:
                          obj.confidence > 0.8
                            ? '#10b981'
                            : obj.confidence > 0.6
                            ? '#f59e0b'
                            : '#ef4444',
                      }}
                    />
                  </div>
                  <span className="confidence-text">
                    {(obj.confidence * 100).toFixed(0)}%
                  </span>
                </div>
                <div className="object-velocity">
                  <span className="velocity-label">Velocity:</span>
                  <span className="velocity-value">
                    {Math.sqrt(
                      obj.boundingBox.velocity.x ** 2 +
                        obj.boundingBox.velocity.y ** 2 +
                        obj.boundingBox.velocity.z ** 2
                    ).toFixed(1)}{' '}
                    m/s
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      <div className="metadata-section">
        <h3 className="metadata-title">Performance</h3>
        <div className="metadata-grid">
          <div className="metadata-item">
            <span className="label">Avg Confidence</span>
            <span className="value">{(avgConfidence * 100).toFixed(0)}%</span>
          </div>
          <div className="metadata-item">
            <span className="label">Processing</span>
            <span className="value">10 FPS</span>
          </div>
        </div>
      </div>
    </div>
  );
}
