import { MapPin, Clock, Cloud, AlertTriangle, Play } from 'lucide-react';
import { Scenario } from '../types';
import { useStore } from '../store';
import { gsap } from 'gsap';

interface Props {
  scenario: Scenario;
}

export default function ScenarioCard({ scenario }: Props) {
  const { selectScenario } = useStore();

  const handleClick = () => {
    selectScenario(scenario);

    // Animate transition
    gsap.to('.search-view', {
      opacity: 0,
      duration: 0.3,
      onComplete: () => {
        gsap.from('.viewer-view', {
          opacity: 0,
          duration: 0.4,
        });
      },
    });
  };

  const getComplexityColor = (complexity: string) => {
    switch (complexity) {
      case 'low':
        return '#10b981';
      case 'medium':
        return '#f59e0b';
      case 'high':
        return '#ef4444';
      case 'critical':
        return '#dc2626';
      default:
        return '#6b7280';
    }
  };

  const formatWeather = (weather: string) => {
    return weather.replace(/_/g, ' ');
  };

  return (
    <div className="scenario-card" onClick={handleClick}>
      <div className="card-thumbnail">
        <div className="thumbnail-placeholder">
          <Play size={48} className="play-icon" />
        </div>
        <div className="card-badge" style={{ background: getComplexityColor(scenario.complexity) }}>
          {scenario.complexity}
        </div>
      </div>

      <div className="card-content">
        <h3 className="card-title">{scenario.title}</h3>
        <p className="card-description">{scenario.description}</p>

        <div className="card-metadata">
          <div className="metadata-item">
            <MapPin size={14} />
            <span>{scenario.location}</span>
          </div>
          <div className="metadata-item">
            <Clock size={14} />
            <span>{scenario.timeOfDay} • {scenario.duration}s</span>
          </div>
          <div className="metadata-item">
            <Cloud size={14} />
            <span>{formatWeather(scenario.weather.precipitation)}</span>
          </div>
          <div className="metadata-item">
            <AlertTriangle size={14} />
            <span>{scenario.eventTimestamps.length} events</span>
          </div>
        </div>

        <div className="card-tags">
          {scenario.tags.slice(0, 4).map((tag, i) => (
            <span key={i} className="tag">
              {tag.replace(/_/g, ' ')}
            </span>
          ))}
          {scenario.tags.length > 4 && (
            <span className="tag more">+{scenario.tags.length - 4}</span>
          )}
        </div>

        <div className="card-stats">
          <div className="stat">
            <span className="stat-label">Objects Tracked</span>
            <span className="stat-value">
              {scenario.lidarFrames[0]?.trackedObjects.length || 0}
            </span>
          </div>
          <div className="stat">
            <span className="stat-label">Frames</span>
            <span className="stat-value">{scenario.lidarFrames.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
}
