import { Play, Pause, SkipBack, SkipForward } from 'lucide-react';
import { Scenario } from '../types';
import { useStore } from '../store';

interface Props {
  scenario: Scenario;
}

export default function PlaybackControls({ scenario }: Props) {
  const { playback, setPlayback } = useStore();

  const togglePlay = () => {
    setPlayback({ isPlaying: !playback.isPlaying });
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setPlayback({ currentTime: time, isPlaying: false });
  };

  const skipBackward = () => {
    const newTime = Math.max(0, playback.currentTime - 1);
    setPlayback({ currentTime: newTime });
  };

  const skipForward = () => {
    const newTime = Math.min(scenario.duration, playback.currentTime + 1);
    setPlayback({ currentTime: newTime });
  };

  const changeSpeed = (speed: number) => {
    setPlayback({ playbackSpeed: speed });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 10);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms}`;
  };

  const progress = (playback.currentTime / scenario.duration) * 100;

  return (
    <div className="playback-controls">
      <div className="timeline-container">
        <input
          type="range"
          min="0"
          max={scenario.duration}
          step="0.1"
          value={playback.currentTime}
          onChange={handleSeek}
          className="timeline-slider"
          style={{
            background: `linear-gradient(to right, #667eea 0%, #667eea ${progress}%, #333 ${progress}%, #333 100%)`,
          }}
        />
      </div>

      <div className="controls-row">
        <div className="time-display">
          <span className="current-time">{formatTime(playback.currentTime)}</span>
          <span className="separator">/</span>
          <span className="total-time">{formatTime(scenario.duration)}</span>
        </div>

        <div className="control-buttons">
          <button className="control-btn" onClick={skipBackward}>
            <SkipBack size={20} />
          </button>
          <button className="control-btn play-btn" onClick={togglePlay}>
            {playback.isPlaying ? <Pause size={24} /> : <Play size={24} />}
          </button>
          <button className="control-btn" onClick={skipForward}>
            <SkipForward size={20} />
          </button>
        </div>

        <div className="speed-controls">
          {[0.25, 0.5, 1, 2].map((speed) => (
            <button
              key={speed}
              className={`speed-btn ${
                playback.playbackSpeed === speed ? 'active' : ''
              }`}
              onClick={() => changeSpeed(speed)}
            >
              {speed}x
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
