import { useState, useEffect, useRef } from 'react';
import { Search, Filter, Clock, Cloud, AlertTriangle } from 'lucide-react';
import { useStore } from '../store';
import { MOCK_SCENARIOS } from '../data/scenarios';
import { semanticSearch, getSuggestedQueries } from '../algorithms/semanticSearch';
import { gsap } from 'gsap';
import ScenarioCard from './ScenarioCard';

export default function SearchView() {
  const {
    searchQuery,
    searchResults,
    filters,
    setSearchQuery,
    setSearchResults,
    setFilters,
  } = useStore();

  const [showFilters, setShowFilters] = useState(false);
  const [suggestedQueries] = useState(() => getSuggestedQueries(MOCK_SCENARIOS));
  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Focus search input on mount
    searchInputRef.current?.focus();
  }, []);

  const handleSearch = (query: string) => {
    setSearchQuery(query);

    if (!query.trim()) {
      setSearchResults(MOCK_SCENARIOS);
      return;
    }

    // Perform semantic search
    const results = semanticSearch(query, MOCK_SCENARIOS, {
      threshold: 0.4,
      maxResults: 10,
    });

    setSearchResults(results);

    // Animate results
    gsap.from('.scenario-card', {
      opacity: 0,
      y: 20,
      stagger: 0.1,
      duration: 0.4,
      ease: 'power2.out',
    });
  };

  const handleSuggestedQuery = (query: string) => {
    handleSearch(query);
  };

  const applyFilters = () => {
    let filtered = MOCK_SCENARIOS;

    if (filters.timeOfDay.length > 0) {
      filtered = filtered.filter((s) => filters.timeOfDay.includes(s.timeOfDay));
    }

    if (filters.weather.length > 0) {
      filtered = filtered.filter((s) =>
        filters.weather.includes(s.weather.precipitation)
      );
    }

    if (filters.complexity.length > 0) {
      filtered = filtered.filter((s) => filters.complexity.includes(s.complexity));
    }

    setSearchResults(filtered);
  };

  const toggleFilter = (
    category: keyof typeof filters,
    value: string
  ) => {
    const current = filters[category];
    const updated = current.includes(value)
      ? current.filter((v) => v !== value)
      : [...current, value];

    setFilters({
      ...filters,
      [category]: updated,
    });
  };

  useEffect(() => {
    if (
      filters.timeOfDay.length > 0 ||
      filters.weather.length > 0 ||
      filters.complexity.length > 0
    ) {
      applyFilters();
    }
  }, [filters]);

  return (
    <div className="search-view">
      <div className="search-section">
        <div className="search-container">
          <div className="search-box">
            <Search className="search-icon" size={24} />
            <input
              ref={searchInputRef}
              type="text"
              className="search-input"
              placeholder="Search edge cases: 'pedestrian crossing during heavy rain'..."
              value={searchQuery}
              onChange={(e) => handleSearch(e.target.value)}
            />
            <button
              className="filter-toggle"
              onClick={() => setShowFilters(!showFilters)}
            >
              <Filter size={20} />
            </button>
          </div>

          {searchQuery === '' && (
            <div className="suggested-queries">
              <p className="suggested-label">Try searching:</p>
              <div className="suggested-chips">
                {suggestedQueries.map((query, i) => (
                  <button
                    key={i}
                    className="suggested-chip"
                    onClick={() => handleSuggestedQuery(query)}
                  >
                    {query}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {showFilters && (
          <div className="filters-panel">
            <div className="filter-group">
              <h3 className="filter-title">
                <Clock size={16} /> Time of Day
              </h3>
              <div className="filter-chips">
                {['dawn', 'day', 'dusk', 'night'].map((time) => (
                  <button
                    key={time}
                    className={`filter-chip ${
                      filters.timeOfDay.includes(time) ? 'active' : ''
                    }`}
                    onClick={() => toggleFilter('timeOfDay', time)}
                  >
                    {time}
                  </button>
                ))}
              </div>
            </div>

            <div className="filter-group">
              <h3 className="filter-title">
                <Cloud size={16} /> Weather
              </h3>
              <div className="filter-chips">
                {['none', 'light_rain', 'heavy_rain', 'snow', 'fog'].map((weather) => (
                  <button
                    key={weather}
                    className={`filter-chip ${
                      filters.weather.includes(weather) ? 'active' : ''
                    }`}
                    onClick={() => toggleFilter('weather', weather)}
                  >
                    {weather.replace('_', ' ')}
                  </button>
                ))}
              </div>
            </div>

            <div className="filter-group">
              <h3 className="filter-title">
                <AlertTriangle size={16} /> Complexity
              </h3>
              <div className="filter-chips">
                {['low', 'medium', 'high', 'critical'].map((complexity) => (
                  <button
                    key={complexity}
                    className={`filter-chip ${
                      filters.complexity.includes(complexity) ? 'active' : ''
                    }`}
                    onClick={() => toggleFilter('complexity', complexity)}
                  >
                    {complexity}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="results-section">
        <div className="results-header">
          <h2 className="results-title">
            {searchResults.length} scenario{searchResults.length !== 1 ? 's' : ''} found
          </h2>
        </div>

        <div className="results-grid">
          {searchResults.map((scenario) => (
            <ScenarioCard key={scenario.id} scenario={scenario} />
          ))}
        </div>

        {searchResults.length === 0 && (
          <div className="no-results">
            <AlertTriangle size={48} />
            <p>No scenarios match your search criteria</p>
            <button
              className="reset-button"
              onClick={() => {
                setSearchQuery('');
                setSearchResults(MOCK_SCENARIOS);
                setFilters({
                  timeOfDay: [],
                  weather: [],
                  objectTypes: [],
                  complexity: [],
                });
              }}
            >
              Reset filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
