import { Vector3 } from '../types';

/**
 * Point cloud processing algorithms for LiDAR data
 * Includes voxel downsampling, ground plane removal, and clustering
 */

/**
 * Generate synthetic LiDAR point cloud data
 * Creates realistic 3D point clouds with objects and ground plane
 */
export function generatePointCloud(
  numPoints: number,
  objects: Array<{ center: Vector3; size: Vector3; type: string }>,
  groundLevel: number = 0
): Float32Array {
  // Format: [x, y, z, r, g, b, intensity] per point
  const pointsPerElement = 7;
  const data = new Float32Array(numPoints * pointsPerElement);

  let idx = 0;

  // Generate ground plane points (30% of points)
  const groundPoints = Math.floor(numPoints * 0.3);
  for (let i = 0; i < groundPoints; i++) {
    const x = (Math.random() - 0.5) * 100;
    const y = groundLevel + (Math.random() - 0.5) * 0.5;
    const z = (Math.random() - 0.5) * 100;

    data[idx++] = x;
    data[idx++] = y;
    data[idx++] = z;
    data[idx++] = 0.4; // r
    data[idx++] = 0.4; // g
    data[idx++] = 0.4; // b
    data[idx++] = 0.5 + Math.random() * 0.3; // intensity
  }

  // Generate object points
  const remainingPoints = numPoints - groundPoints;
  const pointsPerObject = Math.floor(remainingPoints / objects.length);

  for (const obj of objects) {
    let color: [number, number, number];
    let density: number;

    switch (obj.type) {
      case 'pedestrian':
        color = [1.0, 0.3, 0.3]; // Red
        density = 0.8;
        break;
      case 'vehicle':
        color = [0.3, 0.6, 1.0]; // Blue
        density = 0.9;
        break;
      case 'cyclist':
        color = [1.0, 0.8, 0.2]; // Yellow
        density = 0.6;
        break;
      default:
        color = [0.7, 0.7, 0.7]; // Gray
        density = 0.7;
    }

    for (let i = 0; i < pointsPerObject; i++) {
      if (Math.random() > density) continue; // Simulate point density

      // Generate point within bounding box
      const x = obj.center.x + (Math.random() - 0.5) * obj.size.x;
      const y = obj.center.y + (Math.random() - 0.5) * obj.size.y;
      const z = obj.center.z + (Math.random() - 0.5) * obj.size.z;

      data[idx++] = x;
      data[idx++] = y;
      data[idx++] = z;
      data[idx++] = color[0];
      data[idx++] = color[1];
      data[idx++] = color[2];
      data[idx++] = 0.7 + Math.random() * 0.3;
    }
  }

  return data;
}

/**
 * Voxel downsampling - reduces point cloud size while preserving structure
 * Divides space into voxels and keeps one representative point per voxel
 */
export function voxelDownsample(
  points: Float32Array,
  voxelSize: number = 0.5
): Float32Array {
  const pointsPerElement = 7;
  const numPoints = points.length / pointsPerElement;

  // Create voxel grid
  const voxelMap = new Map<string, number[]>();

  for (let i = 0; i < numPoints; i++) {
    const idx = i * pointsPerElement;
    const x = points[idx];
    const y = points[idx + 1];
    const z = points[idx + 2];

    // Calculate voxel key
    const vx = Math.floor(x / voxelSize);
    const vy = Math.floor(y / voxelSize);
    const vz = Math.floor(z / voxelSize);
    const key = `${vx},${vy},${vz}`;

    // Average points in same voxel
    if (!voxelMap.has(key)) {
      voxelMap.set(key, [0, 0, 0, 0, 0, 0, 0, 0]); // [x,y,z,r,g,b,i,count]
    }

    const voxel = voxelMap.get(key)!;
    for (let j = 0; j < 7; j++) {
      voxel[j] += points[idx + j];
    }
    voxel[7]++;
  }

  // Create downsampled array
  const result = new Float32Array(voxelMap.size * pointsPerElement);
  let idx = 0;

  for (const voxel of voxelMap.values()) {
    const count = voxel[7];
    for (let j = 0; j < 7; j++) {
      result[idx++] = voxel[j] / count;
    }
  }

  return result;
}

/**
 * Remove ground plane using RANSAC algorithm
 * Fits a plane to the lowest points and removes them
 */
export function removeGroundPlane(
  points: Float32Array,
  iterations: number = 100,
  threshold: number = 0.3
): Float32Array {
  const pointsPerElement = 7;
  const numPoints = points.length / pointsPerElement;

  if (numPoints < 3) return points;

  let bestPlane: { a: number; b: number; c: number; d: number } | null = null;
  let maxInliers = 0;

  // RANSAC: Random Sample Consensus
  for (let iter = 0; iter < iterations; iter++) {
    // Randomly select 3 points
    const indices = [
      Math.floor(Math.random() * numPoints),
      Math.floor(Math.random() * numPoints),
      Math.floor(Math.random() * numPoints),
    ];

    const p1 = {
      x: points[indices[0] * pointsPerElement],
      y: points[indices[0] * pointsPerElement + 1],
      z: points[indices[0] * pointsPerElement + 2],
    };
    const p2 = {
      x: points[indices[1] * pointsPerElement],
      y: points[indices[1] * pointsPerElement + 1],
      z: points[indices[1] * pointsPerElement + 2],
    };
    const p3 = {
      x: points[indices[2] * pointsPerElement],
      y: points[indices[2] * pointsPerElement + 1],
      z: points[indices[2] * pointsPerElement + 2],
    };

    // Compute plane equation ax + by + cz + d = 0
    const v1 = { x: p2.x - p1.x, y: p2.y - p1.y, z: p2.z - p1.z };
    const v2 = { x: p3.x - p1.x, y: p3.y - p1.y, z: p3.z - p1.z };

    // Normal vector (cross product)
    const a = v1.y * v2.z - v1.z * v2.y;
    const b = v1.z * v2.x - v1.x * v2.z;
    const c = v1.x * v2.y - v1.y * v2.x;
    const d = -(a * p1.x + b * p1.y + c * p1.z);

    // Normalize
    const norm = Math.sqrt(a * a + b * b + c * c);
    if (norm < 1e-6) continue;

    const plane = {
      a: a / norm,
      b: b / norm,
      c: c / norm,
      d: d / norm,
    };

    // Count inliers
    let inliers = 0;
    for (let i = 0; i < numPoints; i++) {
      const idx = i * pointsPerElement;
      const x = points[idx];
      const y = points[idx + 1];
      const z = points[idx + 2];

      const distance = Math.abs(plane.a * x + plane.b * y + plane.c * z + plane.d);
      if (distance < threshold) {
        inliers++;
      }
    }

    if (inliers > maxInliers) {
      maxInliers = inliers;
      bestPlane = plane;
    }
  }

  if (!bestPlane) return points;

  // Filter out ground points
  const filtered: number[] = [];
  for (let i = 0; i < numPoints; i++) {
    const idx = i * pointsPerElement;
    const x = points[idx];
    const y = points[idx + 1];
    const z = points[idx + 2];

    const distance = Math.abs(
      bestPlane.a * x + bestPlane.b * y + bestPlane.c * z + bestPlane.d
    );

    if (distance >= threshold) {
      for (let j = 0; j < pointsPerElement; j++) {
        filtered.push(points[idx + j]);
      }
    }
  }

  return new Float32Array(filtered);
}

/**
 * Compute bounding box for a cluster of points
 */
export function computeBoundingBox(points: Vector3[]): {
  min: Vector3;
  max: Vector3;
  center: Vector3;
  dimensions: Vector3;
} {
  if (points.length === 0) {
    const zero = { x: 0, y: 0, z: 0 };
    return { min: zero, max: zero, center: zero, dimensions: zero };
  }

  const min = { x: Infinity, y: Infinity, z: Infinity };
  const max = { x: -Infinity, y: -Infinity, z: -Infinity };

  for (const p of points) {
    min.x = Math.min(min.x, p.x);
    min.y = Math.min(min.y, p.y);
    min.z = Math.min(min.z, p.z);
    max.x = Math.max(max.x, p.x);
    max.y = Math.max(max.y, p.y);
    max.z = Math.max(max.z, p.z);
  }

  const center = {
    x: (min.x + max.x) / 2,
    y: (min.y + max.y) / 2,
    z: (min.z + max.z) / 2,
  };

  const dimensions = {
    x: max.x - min.x,
    y: max.y - min.y,
    z: max.z - min.z,
  };

  return { min, max, center, dimensions };
}

/**
 * Calculate point cloud density (points per cubic meter)
 */
export function calculateDensity(points: Float32Array): number {
  const pointsPerElement = 7;
  const numPoints = points.length / pointsPerElement;

  if (numPoints === 0) return 0;

  // Find bounding box
  let minX = Infinity, maxX = -Infinity;
  let minY = Infinity, maxY = -Infinity;
  let minZ = Infinity, maxZ = -Infinity;

  for (let i = 0; i < numPoints; i++) {
    const idx = i * pointsPerElement;
    const x = points[idx];
    const y = points[idx + 1];
    const z = points[idx + 2];

    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
    minZ = Math.min(minZ, z);
    maxZ = Math.max(maxZ, z);
  }

  const volume = (maxX - minX) * (maxY - minY) * (maxZ - minZ);
  return volume > 0 ? numPoints / volume : 0;
}
