import Fuse from 'fuse.js';
import { Scenario } from '../types';

/**
 * Implements semantic search using:
 * 1. Fuzzy string matching (Fuse.js with Levenshtein distance)
 * 2. TF-IDF scoring for relevance ranking
 * 3. Query expansion for synonyms and related terms
 */

// Query expansion map for common AV terminology
const QUERY_EXPANSIONS: Record<string, string[]> = {
  'pedestrian': ['person', 'walker', 'human', 'foot traffic'],
  'vehicle': ['car', 'truck', 'bus', 'automobile'],
  'rain': ['wet', 'precipitation', 'rainy', 'rainfall'],
  'night': ['dark', 'evening', 'nighttime', 'after dark'],
  'crossing': ['intersection', 'crosswalk', 'junction', 'merge'],
  'emergency': ['ambulance', 'fire truck', 'police', 'siren'],
  'construction': ['work zone', 'roadwork', 'construction zone', 'barriers'],
};

/**
 * Calculate TF-IDF scores for document ranking
 * TF (Term Frequency) = count of term in document / total terms in document
 * IDF (Inverse Document Frequency) = log(N / number of documents containing term)
 */
function calculateTFIDF(
  query: string,
  documents: string[],
  targetDoc: string
): number {
  const terms = query.toLowerCase().split(/\s+/);
  const N = documents.length;
  let score = 0;

  for (const term of terms) {
    // Calculate TF
    const termCount = (targetDoc.toLowerCase().match(new RegExp(term, 'g')) || []).length;
    const totalTerms = targetDoc.split(/\s+/).length;
    const tf = termCount / totalTerms;

    // Calculate IDF
    const docsContainingTerm = documents.filter(doc =>
      doc.toLowerCase().includes(term)
    ).length;
    const idf = Math.log(N / (docsContainingTerm + 1)); // +1 to avoid division by zero

    score += tf * idf;
  }

  return score;
}

/**
 * Expand query with synonyms and related terms
 */
function expandQuery(query: string): string {
  const terms = query.toLowerCase().split(/\s+/);
  const expandedTerms = new Set(terms);

  for (const term of terms) {
    if (QUERY_EXPANSIONS[term]) {
      QUERY_EXPANSIONS[term].forEach(synonym => expandedTerms.add(synonym));
    }
  }

  return Array.from(expandedTerms).join(' ');
}

/**
 * Create searchable text from scenario
 */
function createSearchableText(scenario: Scenario): string {
  const parts = [
    scenario.title,
    scenario.description,
    scenario.timeOfDay,
    scenario.weather.precipitation,
    scenario.location,
    scenario.complexity,
    ...scenario.tags,
  ];

  // Add tracked objects
  scenario.lidarFrames.forEach(frame => {
    frame.trackedObjects.forEach(obj => {
      parts.push(obj.type);
    });
  });

  // Add event descriptions
  scenario.eventTimestamps.forEach(event => {
    parts.push(event.description);
  });

  return parts.join(' ');
}

/**
 * Main semantic search function
 */
export function semanticSearch(
  query: string,
  scenarios: Scenario[],
  options: {
    threshold?: number;
    maxResults?: number;
  } = {}
): Scenario[] {
  const { threshold = 0.3, maxResults = 10 } = options;

  if (!query.trim()) {
    return scenarios;
  }

  // Expand query with synonyms
  const expandedQuery = expandQuery(query);

  // Create searchable documents
  const searchableScenarios = scenarios.map(scenario => ({
    scenario,
    text: createSearchableText(scenario),
  }));

  // Configure Fuse.js for fuzzy matching
  const fuse = new Fuse(
    searchableScenarios.map(s => s.text),
    {
      includeScore: true,
      threshold,
      ignoreLocation: true,
      keys: ['text'],
    }
  );

  // Perform fuzzy search
  const fuzzyResults = fuse.search(expandedQuery);

  // Calculate TF-IDF scores for ranking
  const allTexts = searchableScenarios.map(s => s.text);
  const scoredResults = fuzzyResults.map((result) => {
    const scenario = searchableScenarios[result.refIndex].scenario;
    const text = searchableScenarios[result.refIndex].text;

    // Combine fuzzy score (0-1, lower is better) with TF-IDF (higher is better)
    const fuzzyScore = 1 - (result.score || 0);
    const tfidfScore = calculateTFIDF(expandedQuery, allTexts, text);

    // Weighted combination (70% fuzzy, 30% TF-IDF)
    const combinedScore = fuzzyScore * 0.7 + Math.min(tfidfScore, 1) * 0.3;

    return {
      scenario,
      score: combinedScore,
    };
  });

  // Sort by combined score and return top results
  return scoredResults
    .sort((a, b) => b.score - a.score)
    .slice(0, maxResults)
    .map(r => r.scenario);
}

/**
 * Get suggested queries based on available scenarios
 */
export function getSuggestedQueries(scenarios: Scenario[]): string[] {
  const suggestions = new Set<string>();

  // Extract common patterns
  scenarios.forEach(scenario => {
    // Time + Weather patterns
    suggestions.add(`${scenario.timeOfDay} ${scenario.weather.precipitation}`);

    // Object + Weather patterns
    scenario.lidarFrames[0]?.trackedObjects.forEach(obj => {
      suggestions.add(`${obj.type} in ${scenario.weather.precipitation}`);
    });

    // Complex patterns from tags
    if (scenario.tags.length >= 2) {
      suggestions.add(scenario.tags.slice(0, 2).join(' '));
    }
  });

  return Array.from(suggestions).slice(0, 6);
}
