import { useEffect, useRef } from 'react';
import { ArrowLeft } from 'lucide-react';
import { useStore } from '../store';
import LiDARViewer from './LiDARViewer';
import PlaybackControls from './PlaybackControls';
import MetadataOverlay from './MetadataOverlay';
import TimelineEvents from './TimelineEvents';
import { gsap } from 'gsap';

export default function ViewerView() {
  const { selectedScenario, selectScenario, playback, setPlayback } = useStore();
  const animationFrameRef = useRef<number>();

  useEffect(() => {
    // Animate playback if playing
    if (playback.isPlaying && selectedScenario) {
      const startTime = Date.now();
      const startPlaybackTime = playback.currentTime;

      const animate = () => {
        const elapsed = (Date.now() - startTime) / 1000;
        const newTime = startPlaybackTime + elapsed * playback.playbackSpeed;

        if (newTime >= selectedScenario.duration) {
          setPlayback({ isPlaying: false, currentTime: selectedScenario.duration });
        } else {
          setPlayback({ currentTime: newTime });
          animationFrameRef.current = requestAnimationFrame(animate);
        }
      };

      animationFrameRef.current = requestAnimationFrame(animate);

      return () => {
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }
      };
    }
  }, [playback.isPlaying, playback.playbackSpeed, selectedScenario, setPlayback]);

  const handleBack = () => {
    gsap.to('.viewer-view', {
      opacity: 0,
      duration: 0.3,
      onComplete: () => {
        selectScenario(null);
        gsap.from('.search-view', {
          opacity: 0,
          duration: 0.4,
        });
      },
    });
  };

  if (!selectedScenario) {
    return null;
  }

  return (
    <div className="viewer-view">
      <div className="viewer-header">
        <button className="back-button" onClick={handleBack}>
          <ArrowLeft size={20} />
          Back to Search
        </button>
        <div className="viewer-title">
          <h2>{selectedScenario.title}</h2>
          <p>{selectedScenario.description}</p>
        </div>
      </div>

      <div className="viewer-content">
        <div className="viewer-main">
          <div className="lidar-container">
            <LiDARViewer scenario={selectedScenario} />
            <MetadataOverlay scenario={selectedScenario} />
          </div>
        </div>

        <div className="viewer-timeline">
          <TimelineEvents scenario={selectedScenario} />
          <PlaybackControls scenario={selectedScenario} />
        </div>
      </div>
    </div>
  );
}
